import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        long[] a = new long[rows * cols];
        for (int i = 0; i < a.length; i++) a[i] = nextLong();
        StringBuilder sb = new StringBuilder();
        for (int d = 0; d < rows + cols - 1; d++) {
            int low = Math.max(0, d - cols + 1), high = Math.min(rows - 1, d);
            // Even diagonals go up (row descending), odd ones go down.
            for (int t = 0; t <= high - low; t++) {
                int i = d % 2 == 0 ? high - t : low + t;
                if (sb.length() > 0) sb.append(' ');
                sb.append(a[i * cols + d - i]);
            }
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	rows, cols := int(nextInt()), int(nextInt())
	a := make([]int64, rows*cols)
	for i := range a {
		a[i] = nextInt()
	}
	out := make([]byte, 0, 12*len(a)+1)
	for d := 0; d < rows+cols-1; d++ {
		low, high := max(0, d-cols+1), min(rows-1, d)
		// Even diagonals go up (row descending), odd ones go down.
		for t := 0; t <= high-low; t++ {
			i := low + t
			if d%2 == 0 {
				i = high - t
			}
			if len(out) > 0 {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, a[i*cols+d-i], 10)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
